#include <ATen/hip/HIPContext.h>
#include <hip/hip_runtime.h>
#include <torch/library.h>
#include <cstdint>

namespace {
using u32x4 = uint32_t __attribute__((ext_vector_type(4)));
using u32x8 = uint32_t __attribute__((ext_vector_type(8)));
using u16x2 = unsigned short __attribute__((ext_vector_type(2)));

template<int Threads>
__global__ __launch_bounds__(Threads)
void quantize(const uint16_t* __restrict__ x, uint8_t* __restrict__ y,
              uint8_t* __restrict__ scales, int64_t elements) {
    const int64_t slot = int64_t(blockIdx.x) * Threads + threadIdx.x;
    if (slot >= elements / 16) return;
    const u32x8 data = *reinterpret_cast<const u32x8*>(x + slot * 16);
    u16x2 maximum = __builtin_bit_cast(u16x2, data[0] & 0x7FFF7FFFu);
#pragma unroll
    for (int i = 1; i < 8; ++i)
        maximum = __builtin_elementwise_max(maximum, __builtin_bit_cast(u16x2, data[i] & 0x7FFF7FFFu));
    uint32_t max_bits = maximum[0] > maximum[1] ? maximum[0] : maximum[1];
    const uint32_t other = __builtin_amdgcn_mov_dpp(max_bits, 0xB1, 0xF, 0xF, true);
    max_bits = max_bits > other ? max_bits : other;
    const float amax = fmaxf(1e-10f, __builtin_bit_cast(float, max_bits << 16));
    const uint32_t unrounded = __builtin_bit_cast(uint32_t, amax * (1.0f / 448.0f));
    const uint32_t exponent = (unrounded >> 23) + ((unrounded & 0x7FFFFFu) != 0);
    const float scale = __builtin_bit_cast(float, exponent << 23);
    const float inverse = 1.0f / scale;
    u32x4 packed;
#pragma unroll
    for (int i = 0; i < 4; ++i) {
        const uint32_t lo = data[2 * i], hi = data[2 * i + 1];
        const float a = __builtin_bit_cast(float, lo << 16) * inverse;
        const float b = __builtin_bit_cast(float, lo & 0xffff0000u) * inverse;
        const float c = __builtin_bit_cast(float, hi << 16) * inverse;
        const float d = __builtin_bit_cast(float, hi & 0xffff0000u) * inverse;
        int result = __builtin_amdgcn_cvt_pk_fp8_f32(a, b, 0, false);
        result = __builtin_amdgcn_cvt_pk_fp8_f32(c, d, result, true);
        packed[i] = result;
    }
    *reinterpret_cast<u32x4*>(y + slot * 16) = packed;
    if ((threadIdx.x & 1) == 0) scales[slot / 2] = exponent;
}

void run(const at::Tensor& x, at::Tensor& quantized, at::Tensor& scales) {
    const int64_t elements = x.numel();
    auto xp = static_cast<const uint16_t*>(x.data_ptr());
    auto yp = static_cast<uint8_t*>(quantized.data_ptr());
    auto sp = static_cast<uint8_t*>(scales.data_ptr());
    const auto stream = at::hip::getCurrentHIPStream();
    if (elements >= (int64_t{32} << 20))
        quantize<128><<<(elements / 16 + 127) / 128, 128, 0, stream>>>(xp, yp, sp, elements);
    else
        quantize<256><<<(elements / 16 + 255) / 256, 256, 0, stream>>>(xp, yp, sp, elements);
}
} // namespace

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor x, Tensor(a!) quantized, Tensor(b!) scales) -> ()", &run);
}
